	): Effect.Effect<GetV1WorkoutsEvents200, HevyRequestEffectError>;
	getWorkoutCount(
		options?: HevyRequestOptions,
	): Effect.Effect<GetV1WorkoutsCount200, HevyRequestEffectError>;
	getRoutines(
		params?: GetV1RoutinesQuery,
