	): Effect.Effect<PostV1Routines201, HevyRequestEffectError>;
	updateRoutine(
		routineId: string,
		data: PutRoutinesRequestBody,
		options?: HevyRequestOptions,
	): Effect.Effect<PutV1RoutinesRoutineid200, HevyRequestEffectError>;
	getExerciseTemplates(
