export function getRequestEffectClient(
	client: RequestEffectOwner,
): HevyRequestEffectClient {
	const requestEffect = getNativeRequestEffect(client);
	return {
		getWorkouts: (params, options) =>
			requestDataEffect<GetV1Workouts200>(
				requestEffect,
